import contextlib
def out(action, *args):
    """The lines a call prints."""
    buffer = io.StringIO()
    with contextlib.redirect_stdout(buffer):
        action(*args)
    return buffer.getvalue().splitlines()
def error_of(action, *args, **kwargs):
