class Student:
    school = "Green Valley"
    count = 0

    def __init__(self, name):
        Student.count += 1
        self.name = name
        self.roll_no = Student.count

    def info(self):
        print(f"{self.roll_no}: {self.name} ({self.school})")

    @classmethod
    def rename_school(cls, new_name):
        cls.school = new_name

    @classmethod
    def total(cls):
        return cls.count
